    static func make() -> NotesLibrary {
        var idByTitle: [String: String] = [:]
        for (i, s) in seeds.enumerated() { idByTitle[s.title] = String(format: "DEMO0000-0000-0000-0000-%012d", i) }
        let now = Date()
        let notes = seeds.enumerated().map { i, s in
            Note(id: idByTitle[s.title]!, pk: Int64(i + 1), title: s.title, folder: s.folder,
                 // Spread over the last year or so, newest first, in a stable order.
                 modified: now.addingTimeInterval(-Double((i * 37) % 400) * 86_400).rounded(),
                 text: s.title + "\n" + s.body, isLocked: false,
                 userTags: s.tags, linkedIDs: s.links.compactMap { idByTitle[$0] })
        }
        return NotesLibrary(notes: notes, storeUUID: nil, diagnostics: ["sample library: \(notes.count) notes"])
    }
}

private extension Date {
    /// Whole days, so cached entries match between launches.
    func rounded() -> Date {
        let midnight = Calendar.current.startOfDay(for: self)
        return Date(timeIntervalSinceReferenceDate: midnight.timeIntervalSinceReferenceDate.rounded())
    }
}
